def agent_action(sandbox, agent_body, step_count):
    # Get current position
    pos = sandbox.get_craft_position()
    x, y = pos

    # Define target waypoints based on current position
    if x < 12:
        target_x, target_y = 13, 1.9  # Center of Gate 1
    elif x < 22:
        target_x, target_y = 23, 2.4  # Center of Gate 2
    else:
        target_x, target_y = 30, 3.5  # Center of target zone

    # Calculate direction vector to target
    dx = target_x - x
    dy = target_y - y

    # Adjust for gate constraints
    if 12 <= x <= 14:
        # Ensure y is within Gate 1's range [1.0, 2.8]
        if y < 1.0:
            dy += 1.0  # Aggressive upward adjustment
        elif y > 2.8:
            dy -= 1.0  # Aggressive downward adjustment
    elif 22 <= x <= 24:
        # Ensure y is within Gate 2's range [1.8, 3.0]
        if y < 1.8:
            dy += 1.0  # Aggressive upward adjustment
        elif y > 3.0:
            dy -= 1.0  # Aggressive downward adjustment

    # Normalize direction vector
    if dx == 0 and dy == 0:
        # Already at target
        f1, f2 = 0.0, 0.0
    else:
        magnitude = (dx**2 + dy**2)**0.5
        direction_normalized = (dx / magnitude, dy / magnitude)

        # Calculate maximum allowable thrust based on heat
        current_heat = sandbox.get_heat()
        heat_limit = sandbox.get_overheat_limit()
        remaining_steps = 10000 - step_count

        if remaining_steps > 0:
            max_thrust = (heat_limit - current_heat) / remaining_steps
        else:
            max_thrust = 0.0

        # Apply maximum allowable thrust in the direction of the target
        # No capping with a base thrust value; use full allowable thrust
        f1 = direction_normalized[0] * max_thrust
        f2 = direction_normalized[1] * max_thrust

        # Ensure thrust is not negative (prevent backward movement)
        if f1 < 0:
            f1 = 0.0
        if f2 < 0:
            f2 = 0.0

    # Apply thrust
    sandbox.apply_thrust(f1, f2)
